                <div className= | }>
                      {estilo.rotulo}
                    </Badge>
                  </div>
                </li>
              );
            })}
          </ol>
        </SectionCard>
      </div>

      {/* Linha do tempo de transições */}
      <SectionCard
        title=

 } },
        }),
      ),
    );
    let capturado: unknown = null;
