async function toggleAudit(itemId: string) {
  if (expandedAuditId === itemId) {
    setExpandedAuditId(null);
    return;
  }
  setExpandedAuditId(itemId);
  if (auditById[itemId]) return;

  setLoadingAuditId(itemId);
