                          {ROTULO_ACAO[a.acao] ?? a.acao}
                        </p>
                        <p className= | >
                          {a.metodo} {a.endpoint}
                        </p>
                        {!executaDireto && (
                          <p className= | >
                      {fmtDate(ev.criado_em)}
                    </span>
                  )}
                </div>
              </li>
            ))}
          </ul>
        )}
      </SectionCard>

      {/* Confirmação de execução */}
      <ConfirmModal
        open={confirmando !== null}
        onClose={() => setConfirmando(null)}
        onConfirm={() => confirmando && void executar(confirmando)}
        variant= | >
                    {erroAcao.detalhes.map((d, i) => (
                      <li key={i}>{d}</li>
                    ))}
                  </ul>
                )}
              </Alert>
            )}
            {acoes.length === 0 ? (
              <p className= | >
                    {ev.resumo || `Snapshot v${ev.versao}`}
                  </p>
                  <p className= | >
                  Próximo passo recomendado
                </p>
                <p className= | >
                  {prox.passo_recomendado}
                </p>
              </div>
              {ultimaTransicao && (
                <Alert variant= | >
                Nenhuma ação disponível neste estado.
              </p>
            ) : (
              <ul className= | >
                Nenhuma pendência bloqueante neste estado.
              </p>
            ) : (
              <div className= | >
                {pendencias.map((p, i) => (
                  <PendenciaItem key={`${p.tipo}-${i}`} p={p} />
                ))}
              </div>
            )}
          </SectionCard>

          {/* Ações disponíveis */}
          <SectionCard
            title= | >
                {visao.estado_rotulo}
              </Badge>
              <div>
                <p className= | >
            Nenhum evento registrado ainda.
          </p>
        ) : (
          <ul className= | >
          {/* Estado atual + próximo passo */}
          <SectionCard
            title= | >
          {itens.map((i, idx) => (
            <li key={idx}>{i}</li>
          ))}
        </ul>
      )}
    </Alert>
  );
}

export default function OrquestradorPanel({
  caseId,
  casoStatus,
}: {
  caseId: string;
  /** Status do caso — encerrado/arquivado bloqueia a execução de ações
   *  (espelha a guarda 409 do backend em /orquestrador/avancar). */
  casoStatus?: string;
}) {
  const { user } = useAuth();
  const [visao, setVisao] = useState<OrquestradorVisao | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [erroCarga, setErroCarga] = useState(false);
  const [confirmando, setConfirmando] = useState<OrquestradorAcao | null>(null);
  const [executando, setExecutando] = useState(false);
  const [erroAcao, setErroAcao] = useState<{
    titulo: string;
    detalhes: string[];
  } | null>(null);
  const [ultimaTransicao, setUltimaTransicao] = useState<string | null>(null);

  const carregar = useCallback(async () => {
    setCarregando(true);
    setErroCarga(false);
    try {
      setVisao(await visaoOrquestrador(caseId));
    } catch {
      setErroCarga(true);
    } finally {
      setCarregando(false);
    }
  }, [caseId]);

  useEffect(() => {
    void carregar();
  }, [carregar]);

  async function executar(acao: OrquestradorAcao) {
    setExecutando(true);
    setErroAcao(null);
    try {
      const r = await avancarOrquestrador(caseId, acao.acao, {});
      setConfirmando(null);
      if (r.requer_aprovacao_humana) {
        // Defensivo: o painel não envia atos jurídicos, mas se o backend
        // recusar, mostra a instrução do endpoint humano sem executar nada.
        toast.info(r.instrucao ??  | >
        <Spinner />
      </div>
    );
  }
  if (erroCarga && !visao) {
    return (
      <ErrorState
        title= | >
      <IANotice>
        O orquestrador apenas conduz os fluxos oficiais do EJC. Todo conteúdo
        gerado é rascunho sujeito à revisão obrigatória do advogado — nenhuma
        aprovação jurídica acontece automaticamente.
      </IANotice>

      <div className= | >Campos do fluxo:</p>
                <ul className= | >{campo}</span>:{ | >{ev.estado}</Badge>}
                  {ev.criado_em && (
                    <span className= | >{ultimaTransicao}</Alert>
              )}
            </div>
          </SectionCard>

          {/* Pendências bloqueantes */}
          <SectionCard
            title= | }
                  </p>
                </div>
                <div className= | }>
                      {estilo.rotulo}
                    </Badge>
                  </div>
                </li>
              );
            })}
          </ol>
        </SectionCard>
      </div>

      {/* Linha do tempo de transições */}
      <SectionCard
        title=

 } },
        }),
      ),
    );
    let capturado: unknown = null;
    function H() {
      const override = useOverrideCitacoes();
      return (
        <button
          onClick={() =>
            void override.executar(enviar).catch((e) => {
              capturado = e;
            })
          }
        >
          marcar
        </button>
      );
    }
    render(<H />);
    fireEvent.click(screen.getByText( | )).toBeNull();
  });
});

