type RegraId =
   | ../lib/api | ./Toast | ;

// ── Card de uma regra de transição ───────────────────────────────────────────
function CardRegra({
  regra,
  recomendada,
}: {
  regra: RegraTransicao;
  recomendada: boolean;
}) {
  const elegivel = regra.elegivel;
  return (
    <div
      className={`rounded-xl border p-4 relative transition-colors ${
        recomendada
          ?  | >
                  Nenhuma regra elegível ainda
                </span>
              </div>
              <p className= | >
                  RMI estimada
                </div>
              </>
            ) : (
              <div className= | >
                  {fmtBRL(regra.rmi_estimada)}
                </div>
                <div className= | >
                <CheckCircle2 size={11} /> Elegível
              </span>
            ) : (
              <span className= | >
                Ainda não
              </span>
            )}
          </div>
          {regra.base_legal && (
            <span className= | >
                Informe a média do CNIS para estimar a RMI.
              </div>
            )}
          </div>
        </div>
      ) : (
        regra.o_que_falta?.length > 0 && (
          <div className= | >
                {res.melhor_regra.motivo}
              </p>
            </div>
          ) : (
            <div className= | >
              Coeficiente da RMI
            </div>
          </div>
          <div>
            {regra.rmi_estimada != null ? (
              <>
                <div className= | >
              O que falta
            </div>
            <ul className= | >
              {fmtPct(regra.coeficiente_rmi)}
            </div>
            <div className= | >
              {regra.base_legal}
            </span>
          )}
        </div>
      </div>

      {elegivel ? (
        <div className= | >
              {regra.nome}
            </h3>
            {elegivel ? (
              <span className= | >
              {res.base_legal_geral}
            </p>
          )}

          {/* Parecer PDF Visual Law */}
          <div className= | >
            Do CNIS — se não informar, mostramos só o coeficiente e a
            elegibilidade.
          </p>
        </div>
      </div>

      <button
        className= | >
            Média dos salários de contribuição (R$)
          </label>
          <input
            className= | >
            Tempo de contribuição (anos) *
          </label>
          <input
            className= | >
            {res.regras.map((r) => (
              <CardRegra
                key={r.regra_id}
                regra={r}
                recomendada={
                  res.melhor_regra?.id != null &&
                  r.regra_id === res.melhor_regra.id
                }
              />
            ))}
          </div>

          {res.base_legal_geral && (
            <p className= | >
          <Award size={11} /> Recomendada
        </span>
      )}

      <div className= | >
          Estimativa determinística · apoio técnico
        </span>
      </p>

      {/* Banner HITL fixo (âmbar) */}
      <div className= | >
          Simulação de Aposentadoria (EC 103/2019)
        </h2>
      </div>
      <p className= | >
          {/* Banner da melhor regra */}
          {temMelhor ? (
            <div className= | >
          {res?.aviso_hitl || AVISO_HITL_FALLBACK}
        </p>
      </div>

      {/* Formulário */}
      <div className= | >Ano da análise</label>
          <input
            className= | >Feminino</option>
          </select>
        </div>
        <div>
          <label className= | >Idade *</label>
          <input
            className= | >Masculino</option>
            <option value= | >Sexo</label>
          <select
            className= | >{erro}</p>}

      {/* Resultado */}
      {res && (
        <div className= | >•</span>
                  <span>{f}</span>
                </li>
              ))}
            </ul>
          </div>
        )
      )}

      {regra.observacoes?.length > 0 && (
        <ul className= | }
                  {res.regras.find((r) => r.regra_id === res.melhor_regra.id)
                    ?.nome || res.melhor_regra.id}
                </span>
              </div>
              <p className= | }
              </p>
            </div>
          )}

          {/* Cards por regra (as 5) */}
          <div className=

              />
              <span>{o}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

