    }
  };

  // Move ↑/↓ trocando a `ordem` com o vizinho (PATCH em ambos)
  const mover = async (index: number, dir: -1 | 1) => {
    const vizinho = index + dir;
    if (vizinho < 0 || vizinho >= provas.length || reordenando) return;
    const atual = provas[index];
