    djen_oab_numero: numero,
    djen_oab_uf: uf,
  });
  // Sem isto, o menu continuaria exibindo o valor antigo até o próximo
  // login — e o modal reabriria com um dado que não está mais no banco.
  updateUser({
    djen_oab_numero: numero || null,
    djen_oab_uf: uf || null,
  });
  setOabNum(numero);
  setModal(null);
  toast.success(
    remover
      ?  | .
      aria-hidden + tabIndex=-1 tiram-no do fluxo de foco/acessibilidade:
      por ser o primeiro input do DOM, automação e leitores de tela
      podiam atingi-lo por engano (achado A11y da auditoria). */}
  <input
    ref={fileRef}
    type= | ../lib/api | ../lib/iaErro | ../stores/auth | ../stores/theme | ./Toast | ./UserAvatar | /users/me/avatar | ;
    }}
  />

  {open && (
    <div className= | >
          Captura de intimações
        </h3>
        <p className= | >
          O sistema consulta o DJEN diariamente (06h30) pela sua OAB.
        </p>
        <div className= | >
          Tema
        </div>
        <div className= | >
        {user?.full_name}
      </div>
      <div className= | >
        {user?.role}
      </div>
    </div>
    <ChevronDown size={14} className=

              }
            >
              <Icon size={14} />
              {THEME_LABELS[mode]}
            </button>
          ))}
        </div>
      </div>
      <div className= | 
            value={oabNum}
            onChange={(event) =>
              setOabNum(event.target.value.replace(/\D/g,  | 
            value={oabUf}
            onChange={(event) => setOabUf(event.target.value)}
          >
            {UFS_BRASIL.map((uf) => (
              <option key={uf}>{uf}</option>
            ))}
          </select>
        </div>
        <button
          className= | 
          onClick={() => salvarOab(false)}
        >
          Salvar
        </button>
        {user?.djen_oab_numero ? (
          <button
            className= | 
          onClick={() => {
            removerFoto();
            setOpen(false);
          }}
        >
          <Trash2 size={15} /> Remover foto
        </button>
      )}
      <div className= | 
        onClick={() => {
          abrirModalOab();
          setOpen(false);
        }}
      >
        <Gavel size={15} /> Minha OAB (intimações DJEN)
      </button>
      <button
        className= | 
        onClick={() => {
          ativarPush();
          setOpen(false);
        }}
      >
        <BellRing size={15} /> Alertas no celular (push)
      </button>
      <button
        className= | 
        onClick={() => {
          fileRef.current?.click();
          setOpen(false);
        }}
      >
        <Camera size={15} /> Trocar foto de perfil
      </button>
      {user?.avatar_url && (
        <button
          className= | 
        onClick={() => {
          setOpen(false);
          logout();
        }}
      >
        <LogOut size={15} /> Sair
      </button>
    </div>
  )}

  {modal ===  | 
        onClick={() => {
          void copiarIcs();
          setOpen(false);
        }}
      >
        <CalendarPlus size={15} /> Copiar link do calendário
      </button>
      <button
        className= | 
        onClick={() => {
          void rotacionarIcs();
          setOpen(false);
        }}
      >
        <RotateCcw size={15} /> Revogar e gerar novo link
      </button>
      <button
        className= | 
      : `OAB ${numero}/${uf} salva — intimações DJEN serão capturadas diariamente às 06h30.`,
  );
} catch (e) {
  toast.error(mensagemErroHttp(e,  |  />
      <button
        className= |  />
      <div className= |  />
    <div className= |  />
  </button>

  {/* Input oculto acionado apenas pelo item  | ))
            }
          />
          <select
            className= | );
          setOpen(false);
        }}
      >
        <KeyRound size={15} /> Trocar senha
      </button>
      <div className= | ,
  );
  return;
}
