    [events],
  );

  const dias = useMemo(() => {
    const inicio = startOfWeek(mesVisivel, { weekStartsOn: 0 });
    const fim = endOfWeek(endOfMonth(mesVisivel), { weekStartsOn: 0 });
    return eachDayOfInterval({ start: inicio, end: fim });
  }, [mesVisivel]);

  const dow = useMemo(() => {
