  const [catalogoIndisponivel, setCatalogoIndisponivel] = useState(false);
  const [valor, setValor] = useState( | >Catálogo BCB indisponível</Badge>
        ) : (
          <Badge tone= | >Competência</th>
                <th className= | >Fator acumulado</th>
              </tr>
            </thead>
            <tbody className= | >Fonte oficial · BCB</Badge>
        )
      }
    >
      <form onSubmit={calcular} className= | >{l.competencia}</td>
                  <td className= | >{regraInfo.hint}</p>
          )}
        </div>

        <Button
          type= | >Índice (%)</th>
                <th className= | Correção + Taxa Legal (Lei 14.905/2024) | Perfil do
// julgador | SELIC exclusiva (EC 113/2021 — Fazenda Pública) | rounded-xl border border-slate-100 bg-slate-50/60 p-3 | }
                  )
                </p>
              </div>
              <div className= | }
                  {fmtMoney(resultado.comparativo.custo_do_tempo)}
                </span>
                <p className= | }
                  — acima disso o acordo tende a superar o litígio.
                </p>
              </div>
            </div>

            {/* Barra comparativa proporcional */}
            <BarraComparativa resultado={resultado} />

            {/* Custo do tempo */}
            <div className= | }
                </option>
              ))}
            </Select>
            {usaIndice && selInfo?.ultimo_valor != null && (
              <p className= | }
              </p>
            )}
            {!usaIndice && (
              <p className= | }
              {(resultado.parametros.selic_anual * 100).toFixed(2)}% a.a.
            </Badge>
          }
        >
          <div className= | }
          </Button>
        </form>
      </SectionCard>

      {calculando && <Spinner />}

      {resultado && !calculando && (
        <SectionCard
          title= | }
        </Button>
      </form>

      {calculando && <Spinner />}

      {resultado && !calculando && (
        <div className= | }
        </span>
      </div>
      {linhas.length > 0 && (
        <div className= | })
            </div>
            {resultado.etapas.map((etapa, i) => (
              <MemoriaEtapa key={i} etapa={etapa} />
            ))}
          </div>
        </div>
      )}
    </SectionCard>
  );
}

