      setErroSincronizacao(
        typeof detail ===  | ../components/UI | ../lib/api | >
                          {m.complemento}
                        </p>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {mensagemSincronizacao && (
            <div className= | >
                        {label}
                      </p>
                      <p className= | >
                        {value}
                      </p>
                    </div>
                  ),
              )}
            </div>
          </div>

          {processo.partes && processo.partes.length > 0 && (
            <div className= | >
                      {fmtDate(m.data)}
                    </span>
                    <div>
                      <p className= | >
                      {p.tipo}
                    </span>
                    <span className= | >
                    {processo.situacao}
                  </span>
                )}
                {idCasoContexto && (
                  <button
                    type= | >
                    {processo.tribunal}
                  </p>
                )}
              </div>
              <div className= | >
                  {processo.numero}
                </h2>
                {processo.tribunal && (
                  <p className= | >
          Consulta aberta a partir de um Caso. Confira o processo antes de
          sincronizar movimentações com o cadastro interno.
        </div>
      )}

      <div className= | >
          Ex: 1234567-89.2023.8.26.0000 · Os dados vêm do DataJud CNJ em tempo
          real
        </p>
      </div>

      {erro && (
        <div className= | >
          Número do processo (CNJ)
        </label>
        <div className= | >{erroSincronizacao}</p>
        </div>
      )}

      {processo && (
        <div className= | >{erro}</p>
        </div>
      )}

      {erroSincronizacao && (
        <div className= | >{m.descricao}</p>
                      {m.complemento && (
                        <p className= | >{p.nome}</span>
                  </div>
                ))}
              </div>
            </div>
          )}

          {processo.movimentos && processo.movimentos.length > 0 && (
            <div className= | }
                  </button>
                )}
              </div>
            </div>
            <div className=

                  />
                  <button
                    type= | 
                  >
                    Copiar URL
                  </button>
                </div>
                {linkRecemGerado.expira_em && (
                  <p className= | 
                >
                  <span>{a.nome_exibicao || a.document_id}</span>
                  <span className= | 
              >
