export function Confirmacao({
  proposta,
  onChange,
  usuarios,
  criando,
  erro409,
  onCriar,
  onDescartar,
}: {
  proposta: Proposta;
  onChange: (patch: Partial<Proposta>) => void;
  usuarios: User[];
  criando: boolean;
