  const precisaConfirmarDuplicado = proposta.duplicados.length > 0;

  const podeCriar =
    proposta.confirmoRevisao &&
    (!precisaConfirmarConflito || proposta.conflictConfirmed) &&
    (!precisaConfirmarDuplicado || proposta.duplicateConfirmed) &&
