export default function PortalCasoDetalhe() {
  const { id } = useParams();
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState(false);

  const load = useCallback(() => {
    setError(false);
    setData(null);
    api
      .get(`/portal/casos/${id}`)
      .then((r) => setData(r.data))
      .catch(() => setError(true));
  }, [id]);

  useEffect(() => {
    load();
  }, [load]);

  if (error)
    return (
      <ErrorState
        message= | 
        onRetry={load}
      />
    );
  if (!data) return <Spinner />;
  const { caso, andamentos, proximas_datas } = data;
  // O backend ordena os andamentos do mais recente para o mais antigo — o
  // primeiro é a última movimentação do processo.
  const ultimo =
    Array.isArray(andamentos) && andamentos.length > 0 ? andamentos[0] : null;

  return (
    <div>
      <Link
        to= | 
      >
        <ArrowLeft size={15} /> Voltar
      </Link>
      <div className= |  />
                <div>
                  <div className= | );
  const [sending, setSending] = useState(false);
  const carregar = () =>
    api
      .get(`/portal/casos/${caseId}/mensagens`)
      .then((r) => setMsgs(asList(r.data)))
      .catch(() => {});
  useEffect(() => {
    carregar();
  }, [caseId]);
  const enviar = async () => {
    if (!txt.trim()) return;
    setSending(true);
    try {
      await api.post(`/portal/casos/${caseId}/mensagens`, { mensagem: txt });
      setTxt( | )}
                </span>
              </div>
            ),
          )}
        </div>
      )}

      <div className= | ../../components/Toast | ../../components/UI | ../../lib/api | ../../lib/list | >
            <CalendarClock size={16} /> Próximas datas
          </h2>
          {(Array.isArray(proximas_datas) ? proximas_datas : []).map(
            (d: any, i: number) => (
              <div
                key={i}
                className= | >
            <History size={16} /> Última atualização
          </h2>
          <p className= | >
            Nenhuma mensagem ainda. Envie uma dúvida ao escritório.
          </p>
        )}
      </div>
      <div className= | >
            {ultimo.descricao}
          </p>
        </div>
      )}

      {Array.isArray(proximas_datas) && proximas_datas.length > 0 && (
        <div className= | >
          {caso.numero_processo || caso.numero_interno}
          {caso.comarca && ` · ${caso.comarca}`}
          {caso.vara && ` · ${caso.vara}`}
        </div>
