function CompanyDetailByIdFallback({
  data,
  clientId,
}: {
  data: DptDashboard;
  clientId: string;
}) {
  const [company, setCompany] = useState<CompanyDetailHeader | null>(null);
  const [notFound, setNotFound] = useState(false);
  const [loadError, setLoadError] = useState(false);
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let active = true;
    setCompany(null);
    setNotFound(false);
    setLoadError(false);
    getDptCompanyProfile(clientId)
      .then((profile) => {
        if (!active) return;
        setCompany({
          id: profile.id,
          nome: profile.nome,
          cidade: profile.cidade,
          estado: profile.estado,
        });
      })
      .catch((err: unknown) => {
        if (!active) return;
        if (isClienteForaDoPrograma(err)) {
          setNotFound(true);
        } else {
          setLoadError(true);
        }
      });
    return () => {
      active = false;
    };
  }, [clientId, attempt]);

  if (notFound) {
    // 404 aqui é estado de negócio: o cliente existe no EJC, mas está fora
    // do programa DPT 360 — comunica o enquadramento em vez de erro genérico.
    return <ClienteNaoAcompanhado clientId={clientId} />;
  }
  if (loadError) {
    return (
      <ErrorState
        message= | ) {
    content = <CasesView data={data} />;
  } else if (segments[0] in LEGACY_DPT360_REDIRECTS) {
    // Deep-link legado da navegação antiga: retorna ao destino canônico em
    // vez de deixar a URL morta ou exibir página de erro.
    return (
      <div className= | );
  return year && month && day ? `${day}/${month}/${year}` : value;
}

